function enterPublic(place){if(place)enterHome(place.id,{...place,kind:place.kind||'lobby'});}
function leaveHome(){state.x=inside.x;state.z=inside.z;inside=null;removeInterior();toast('Back to the coast.');}
function interact(){if(inside){if(Math.hypot(inside.ix,inside.iz-9)<4)leaveHome();else if(inside.place)openPanel('City');return;}if(!near)return;if(near.type==='crime')send({type:'crime',id:near.crime});if(near.type==='business'){enterPublic(PLACES.find(p=>p.id===near.place));return;}if(near.type==='building'){enterPublic(near.building);return;}if(near.type==='visit')toast(near.name+' · Take a moment. The coast is yours.');if(near.type==='shop')openPanel(near.tab);if(near.type==='property')enterHome(near.item);if(near.type==='job'){openPanel('Jobs');}}

