function vehicleRadius(id){const b=CATALOG.find(i=>i.id===id)?.body;return b==='bus'?4.4:b==='limo'?3.9:['van','wagon','pickup'].includes(b)?3.3:2.8;}
function collision(x,z){if((!onLand(x,z)&&!atPier(x,z))||x<-700||x>1430||Math.abs(z)>800)return true;const r=state.mode==='car'?vehicleRadius(state.vehicle):.4;for(const s of solids)if(Math.abs(x-s.x)<s.w+r&&Math.abs(z-s.z)<s.d+r)return true;for(const t of traffic)if(Math.abs(x-t.o.position.x)<1.2+r&&Math.abs(z-t.o.position.z)<2.7+r)return true;for(const remote of remotes.values())if(['car','foot'].includes(remote.mode)&&Math.hypot(x-remote.x,z-remote.z)<r+(remote.mode==='car'?vehicleRadius(remote.vehicle):.45))return true;return false;}
function moveGround(dx,dz,slide=true){const steps=Math.max(1,Math.ceil(Math.hypot(dx,dz)/.35));let hit=false;for(let i=0;i<steps;i++){const nx=state.x+dx/steps,nz=state.z+dz/steps;if(state.mode==='car'&&Math.abs(groundHeight(nx,nz)-groundHeight(state.x,state.z))>.35*Math.tan(.65)){hit=true;break;}if(!collision(nx,nz)){state.x=nx;state.z=nz;}else if(slide){if(!collision(nx,state.z))state.x=nx;else hit=true;if(!collision(state.x,nz))state.z=nz;else hit=true;}else{hit=true;break;}}return !hit;}
